#include <iostream>
#include <vector>

using namespace std;

const int MAXS = 1005;
bool adj[MAXS][MAXS];

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int S, T;
    if (!(cin >> S >> T)) return 0;

    for (int i = 0; i < T; ++i) {
        int u, v;
        cin >> u >> v;
        adj[u][v] = true;
        adj[v][u] = true;
    }

    int P;
    cin >> P;

    int valid_tours = 0;
    for (int i = 0; i < P; ++i) {
        int N;
        cin >> N;
        vector<int> tour(N);
        for (int j = 0; j < N; ++j) {
            cin >> tour[j];
        }

        bool possible = true;
        for (int j = 0; j < N - 1; ++j) {
            if (!adj[tour[j]][tour[j + 1]]) {
                possible = false;
                break;
            }
        }

        if (possible) {
            valid_tours++;
        }
    }

    cout << valid_tours << "\n";

    return 0;
}
